"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["2769"],{6493(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>c});var o=JSON.parse('{"id":"how-to/mqttlens","title":"Simulate a system with MQTTLens","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/how-to/mqttlens.md","sourceDirName":"how-to","slug":"/how-to/mqttlens","permalink":"/personal-av-docs/docs/how-to/mqttlens","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/how-to/mqttlens.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Simulate a system with MQTTLens","sidebar_label":"Simulate a system with MQTTLens","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/howto/mqttlens","format":"md"}}'),a=n(4848),i=n(8453);let s={title:"Simulate a system with MQTTLens",sidebar_label:"Simulate a system with MQTTLens",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/howto/mqttlens",format:"md"},r,c={},l=[];function d(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/av/howto/mqttlens",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsx)(t.p,{children:'Simulate a system with MQTTLens\n1 /\nRegister\n2 /\nConfigure\n3 /\nCommunicate\nIntroduction\nMQTTLens\nis a\nchrome\napplication which supports MQTT communications. You can use it to simulate a single system communicating with AirVantage via MQTT.\nPrerequisites\nMQTTLens\nmust be installed on your computer.\nUnderstand the basics of MQTT. Refer to\npage\nfor an introduction.\nStep 1: Register your device\nThe first step is to declare a system in AirVantage, providing an  identifier. We call this the Serial Number.\nWhat is a system?\nA system is the AirVantage representation of any connected device, it includes:\nGateway/modules providing the connectivity\nSIM cards providing access to the wireless network (optional)\nSome applications running on the connected device (embedded firmware & software)\nAn application must be associated within this system in order to define how it will communicate with AirVantage: protocol used, credentials, data sent and/or commands available.\nThe application we use in this tutorial defines MQTT communications sending 3 data types: temperature, luminosity and humidity. For your convenience, this application has already been published in AirVantage, so that you can use it.\nTo know more about applications and how to release your own application, refer to\ntutorial\n.\nAdd required information to your system\nGo to\nMonitor > Systems\nand select your system by checking the check box on the left\nEdit your system by clicking on Edit in the table\u2019s menu More\nAdd a gateway by clicking on the + button in the\nGateway\nsection\nSpecify the Serial Number. Remember it, you will use it in the next step\nClick on Create\nAssociate your application, by clicking on the glass icon in the\nApplications\nsection\nSearch\nGeneric Greenhouse\nin the filter Name\nClick on the application\nSet a password by clicking on the padlock on the right, fill it and click on\nContinue\n. Note it safely, as you will use it in the next step\nSave your modifications\nStep 2: Configure MQTT Lens\nIn the previous step, you specified a system and how it will communicate with AirVantage. Now let\u2019s configure MQTTLens to connect and send data.\nMQTTLens can send MQTT messages to AirVantage exactly like a real system.\nAirVantage address configuration\nClick on the + button to create a new connection\nGive it a name\nAirVantage\nSpecify the hostname:\neu.airvantage.net\n(default port is correct)\nSupply your credentials: fill\nUsername\nwith the Serial Number, and the\nPassword\nwith the password your supplied in the previous step.\nClick on\nSave Changes\nYour connection status must be green:\nSubscribe to topics\nLet\u2019s subscribe to a topic in order to receive notification of commands from AirVantage.\nThe first line in MQTT Lens allows you to susbcribe to a topic. For command, you need to subscribe to {Serial Number}/tasks/json\nThus fill in the Subscribe field accordingly and click on the Subscribe button on the right:\nA new line is added at the bottom of the MQTTLens screen:\nYou can subscribe to the errors topic:\n{Serial Number}/errors\nto be notified when a payload will occur, later in this tutorial.\nStep 3: Send data and receive commands\nMQTT Lens is now connected to AirVantage. Let\u2019s start by sending data and then receive a command.\nSend data to AirVantage\nSending data to AirVantage consists in sending to a topic called\n{Serial Number}/messages/json\nthe following json content:\n{ "1349907137000": { "machine.temperature": 23.2, "machine.humidity": 70 },\n"1349908137000": { "machine.temperature": 24.5 },\n"1349909137000": { "machine.temperature": 22.9 },\n"1349910137000": { "machine.threshold": 30}\n}\nAs in this screenshot:\nYou can check the data has been sent by looking at the system in AirVantage:\nGo to\nMonitor > Systems\nand select your system with the check box on the left\nClick on the Timeline button to see the timeline of communications for the device: MQTT connections and data sent.\nor Click on the Green house application in your system to access the history of values sent for each data type defined for this application.\nTo learn more about the AirVantage json format, refer to\npage\nTroubleshoot payload errors\nTo receive notifications when AirVantage cannot understand the payload sent, AirVantage provides a topic you can subscribe to.\nAs an example showing what happens when you send a bad paylod, you can try to publish the following payload with a missing } char at the beginning of the message :\n"1349907137000": { "machine.temperature": 23.2, "machine.humidity": 70 },\n"1349908137000": { "machine.temperature": 24.5 },\n"1349909137000": { "machine.temperature": 22.9 },\n"1349910137000": { "machine.threshold": 30}\n}\nYou will receive this notification:\nReceive and acknowledge commands\nOn AirVantage, in the system details, click on the menu More on the top.\nSelect your application (Generic Greenhouse)\nSelect your command and parameter\nClick on Send Command button\nYou can check the status of this operation in AirVantage.\nSend back the operation uid provided in the command to acknowledge it and update the status Failed or Success in AirVantage.\nIn the publish section:\nFill the topic name with\n{Serial Number}/acks/json\nThe payload with one of the following content:\nNote you have to use the\nuid\nfrom the task\u2019s message (see above for an example) not from the command\u2019s operation in the ui.\nTo receive success acknowledgements (change the uid accordingly), status must be OK:\n[\n{"uid": "8006cc58ba2141f69161a78f1bfdea1d", "status" : "OK"}\n]\nor for failed acknowledgement (change the uid accordingly), set status to any other value except OK (ERROR, KO):\n[\n{"uid": "3c12547b613740adb686271bdc8f097c", "status" : "ERROR", "message" : "Crashed in flames! Error code: 12345"}\n]\nYou now know how to simulate a single system in order to understand how your system can communicate to AirVantage or to generate specific business contente in order to test accurately your APIs without any real system.\nNext Steps\nIf you wish to simulate a fleet of systems, refer to\ntutorial\n.\nTo learn more about MQTT, use the resources from this\npage\n.\nOn this page, you can access the time series format, which allows your device to send a compressed data history to AirVantage.\nTo know more about errors topic, refer to\npage\n.\nTo learn more about communicating with AirVantage via MQTT, refer to\npage\nAnd please also take a look at our\ntutorials\n, which explain how to develop embedded applications!'})]})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var o=n(6540);let a={},i=o.createContext(a);function s(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);